import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";

// --- Font Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema ---


export type LineChartInfographicProps = Record<string, any>;

// --- Helper: Smooth Path Generator (Catmull-Rom spline to Bezier) ---
const getSmoothPath = (points: [number, number][], smoothing = 0.2) => {
  const line = (pointA: number[], pointB: number[]) => {
    const lengthX = pointB[0] - pointA[0];
    const lengthY = pointB[1] - pointA[1];
    return {
      length: Math.sqrt(Math.pow(lengthX, 2) + Math.pow(lengthY, 2)),
      angle: Math.atan2(lengthY, lengthX),
    };
  };

  const controlPoint = (
    current: number[],
    previous: number[],
    next: number[],
    reverse: boolean
  ) => {
    const p = previous || current;
    const n = next || current;
    const o = line(p, n);
    const angle = o.angle + (reverse ? Math.PI : 0);
    const length = o.length * smoothing;
    const x = current[0] + Math.cos(angle) * length;
    const y = current[1] + Math.sin(angle) * length;
    return [x, y];
  };

  const bezierCommand = (point: number[], i: number, a: number[][]) => {
    const [cpsX, cpsY] = controlPoint(a[i - 1], a[i - 2], point, false);
    const [cpeX, cpeY] = controlPoint(point, a[i - 1], a[i + 1], true);
    return `C ${cpsX},${cpsY} ${cpeX},${cpeY} ${point[0]},${point[1]}`;
  };

  const d = points.reduce((acc, point, i, a) => {
    if (i === 0) return `M ${point[0]},${point[1]}`;
    return `${acc} ${bezierCommand(point, i, a)}`;
  }, "");

  return d;
};

// --- Component ---
const LineChartInfographic: React.FC<LineChartInfographicProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "LINE CHART INFOGRAPHIC",
  targetLabel = "Target",
  productLabel = "Product sale",
  targetColor = "#1e3a8a",
  productColor = "#22d3ee",
  gridColor = "#e5e7eb",
  textColor = "#000000",
  // Data Defaults
  targetData = [12, 50, 40, 55, 50, 30],
  productData = [30, 25, 45, 40, 70, 68],
  chartLabels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun"],
  maxYValue = 80,
  yAxisStep = 25,
}) => {
  useFontLoader(["Oswald", "Roboto"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Configuration ---
  const chartHeight = height * 0.6;
  const chartWidth = width * 0.8;
  const startX = (width - chartWidth) / 2;
  const startY = (height - chartHeight) / 2 + 100;
  const xAxisY = startY + chartHeight;

  // Generate Y Axis Labels based on steps and max value
  const yAxisLabels = useMemo(() => {
    const steps = [];
    let current = 0;
    while (current < maxYValue) {
      steps.push(current);
      current += yAxisStep;
    }
    return steps;
  }, [maxYValue, yAxisStep]);

  // Convert raw data to coordinates
  const getCoords = (data: number[]) => {
    const safeDenominator = data.length > 1 ? data.length - 1 : 1;
    return data.map((val, i) => {
      const x = startX + (i / safeDenominator) * chartWidth;
      const y = xAxisY - (val / maxYValue) * chartHeight;
      return [x, y] as [number, number];
    });
  };

  const targetPoints = useMemo(
    () => getCoords(targetData),
    [targetData, startX, xAxisY, chartWidth, chartHeight, maxYValue]
  );
  const productPoints = useMemo(
    () => getCoords(productData),
    [productData, startX, xAxisY, chartWidth, chartHeight, maxYValue]
  );

  const targetPath = useMemo(() => getSmoothPath(targetPoints), [targetPoints]);
  const productPath = useMemo(
    () => getSmoothPath(productPoints),
    [productPoints]
  );

  // --- Animations ---

  // 1. Grid & Axis Entrance
  const gridProgress = spring({
    frame: frame - 10,
    fps,
    config: { damping: 100 },
  });

  // 2. Line Drawing
  const lineStartFrame = 30;
  const lineDuration = 60; // 2 seconds approx
  const lineProgress = interpolate(
    frame,
    [lineStartFrame, lineStartFrame + lineDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Evolve paths
  const targetEvolved = evolvePath(lineProgress, targetPath);
  const productEvolved = evolvePath(lineProgress, productPath);

  // 3. Title & Legend Entrance
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, 20], [20, 0], {
    extrapolateRight: "clamp",
    easing: (t) => t * (2 - t),
  });

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Roboto",
        color: textColor,
      }}
    >
      {/* Title Section */}
      <div
        style={{
          position: "absolute",
          top: 80,
          left: startX,
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
        }}
      >
        <h1
          style={{
            fontFamily: "Oswald",
            fontSize: 90,
            lineHeight: 1,
            margin: 0,
            textTransform: "uppercase",
          }}
        >
          {titleText.split(" ").slice(0, 2).join(" ")} <br />
          {titleText.split(" ").slice(2).join(" ")}
        </h1>
      </div>

      {/* Legend */}
      <div
        style={{
          position: "absolute",
          top: 100,
          right: startX,
          display: "flex",
          flexDirection: "column",
          gap: 30,
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 15 }}>
          <div
            style={{
              width: 20,
              height: 20,
              backgroundColor: targetColor,
            }}
          />
          <span style={{ fontSize: 32, fontWeight: 500 }}>{targetLabel}</span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 15 }}>
          <div
            style={{
              width: 20,
              height: 20,
              backgroundColor: productColor,
            }}
          />
          <span style={{ fontSize: 32, fontWeight: 500 }}>{productLabel}</span>
        </div>
      </div>

      {/* Chart Area */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, overflow: "visible" }}
      >
        {/* Y Axis Grid Lines & Labels */}
        {yAxisLabels.map((val, i) => {
          const yPos = xAxisY - (val / maxYValue) * chartHeight;
          const labelOpacity = interpolate(
            frame,
            [15 + i * 5, 30 + i * 5],
            [0, 1],
            { extrapolateRight: "clamp" }
          );

          return (
            <g key={`grid-${val}`}>
              {/* Grid Line */}
              <line
                x1={startX}
                y1={yPos}
                x2={startX + chartWidth * gridProgress}
                y2={yPos}
                stroke={gridColor}
                strokeWidth={2}
                opacity={0.5}
              />
              {/* Label */}
              <text
                x={startX - 20}
                y={yPos + 8}
                textAnchor="end"
                fill={textColor}
                fontSize={24}
                fontWeight="bold"
                opacity={labelOpacity}
                style={{ fontFamily: "Roboto" }}
              >
                {val}
              </text>
            </g>
          );
        })}

        {/* X Axis Labels */}
        {chartLabels.map((label, i) => {
          const denominator =
            chartLabels.length > 1 ? chartLabels.length - 1 : 1;
          const xPos = startX + (i / denominator) * chartWidth;
          const labelOpacity = interpolate(
            frame,
            [25 + i * 3, 40 + i * 3],
            [0, 1],
            { extrapolateRight: "clamp" }
          );

          return (
            <text
              key={`x-label-${i}`}
              x={xPos}
              y={xAxisY + 40}
              textAnchor="middle"
              fill={textColor}
              fontSize={24}
              fontWeight="bold"
              opacity={labelOpacity}
              style={{ fontFamily: "Roboto" }}
            >
              {label}
            </text>
          );
        })}

        {/* Target Line (Dark Blue) */}
        <path
          d={targetPath}
          stroke={targetColor}
          strokeWidth={5}
          fill="none"
          strokeLinecap="round"
          strokeDasharray={targetEvolved.strokeDasharray}
          strokeDashoffset={targetEvolved.strokeDashoffset}
        />

        {/* Product Line (Cyan) */}
        <path
          d={productPath}
          stroke={productColor}
          strokeWidth={5}
          fill="none"
          strokeLinecap="round"
          strokeDasharray={productEvolved.strokeDasharray}
          strokeDashoffset={productEvolved.strokeDashoffset}
        />

        {/* Data Points (Target) */}
        {targetPoints.map((point, i) => {
          const safeDenominator =
            targetPoints.length > 1 ? targetPoints.length - 1 : 1;
          const pointProgress = i / safeDenominator;
          const appearThreshold = lineStartFrame + pointProgress * lineDuration;

          const scale = spring({
            frame: frame - appearThreshold,
            fps,
            config: { stiffness: 200, damping: 10 },
          });

          return (
            <g
              key={`t-dot-${i}`}
              transform={`translate(${point[0]}, ${point[1]}) scale(${scale})`}
            >
              {/* Outer white circle */}
              <circle r={8} fill={backgroundColor} />
              {/* Inner colored dot - Fixed: using SVG circle for perfect centering */}
              <circle r={6} fill={targetColor} />
            </g>
          );
        })}

        {/* Data Points (Product) */}
        {productPoints.map((point, i) => {
          const safeDenominator =
            productPoints.length > 1 ? productPoints.length - 1 : 1;
          const pointProgress = i / safeDenominator;
          const appearThreshold = lineStartFrame + pointProgress * lineDuration;

          const scale = spring({
            frame: frame - appearThreshold,
            fps,
            config: { stiffness: 200, damping: 10 },
          });

          return (
            <g
              key={`p-dot-${i}`}
              transform={`translate(${point[0]}, ${point[1]}) scale(${scale})`}
            >
              {/* Outer white circle */}
              <circle r={8} fill={backgroundColor} />
              {/* Inner colored dot - Fixed: using SVG circle for perfect centering */}
              <circle r={6} fill={productColor} />
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default LineChartInfographic;